266	    assert(acceptedCharacters != null);
267	    assert(acceptedCharacters.isNotEmpty);
268	    assert(prompt == null || prompt.isNotEmpty);
269	    assert(displayAcceptedCharacters != null);
270	    if (!usesTerminalUi) {
271	      throw StateError('cannot prompt without a terminal ui');
272	    }
273	    List<String> charactersToDisplay = acceptedCharacters;
274	    if (defaultChoiceIndex != null) {
275	      assert(defaultChoiceIndex >= 0 && defaultChoiceIndex < acceptedCharacters.length);
276	      charactersToDisplay = List<String>.of(charactersToDisplay);
277	      charactersToDisplay[defaultChoiceIndex] = bolden(charactersToDisplay[defaultChoiceIndex]);
278	      acceptedCharacters.add('
');
279	    }
280	    String choice;
281	    singleCharMode = true;
282	    while (choice == null || choice.length > 1 || !acceptedCharacters.contains(choice)) {
283	      if (prompt != null) {
284	        logger.printStatus(prompt, emphasis: true, newline: false);
285	        if (displayAcceptedCharacters) {
286	          logger.printStatus(' [${charactersToDisplay.join("|")}]', newline: false);
287	        }
288	        logger.printStatus(': ', emphasis: true, newline: false);
289	      }
290	      choice = await keystrokes.first;
291	      logger.printStatus(choice);
292	    }
293	    singleCharMode = false;
294	    if (defaultChoiceIndex != null && choice == '
') {
295	      choice = acceptedCharacters[defaultChoiceIndex];
296	    }
297	    return choice;
298	  }
